 1→export interface ColumnInfo {
 2→  name: string;
 3→  type: string;
 4→}
 5→
 6→export interface TableInfo {
 7→  name: string;
 8→  columns: ColumnInfo[];
 9→  rowCount: number;
10→}
11→
12→export interface QueryResult {
13→  columns: string[];
14→  rows: Record<string, unknown>[];
15→  rowCount: number;
16→  executionTimeMs: number;
17→  resultType: 'table' | 'markdown';
18→}
19→
20→export interface ToolCallResult {
21→  toolCallId: string;
22→  toolName?: string;
23→  sql: string;
24→  command?: string;
25→  toolInput?: Record<string, unknown>;
26→  columns: string[];
27→  rows: Record<string, unknown>[];
28→  rowCount: number;
29→  error?: string;
30→  output?: string;
31→  rawContent?: string;
32→  chart_spec?: {
33→    data: unknown[];
34→    layout?: Record<string, unknown>;
35→  };
36→}
37→
38→export interface ContentSegment {
39→  type: 'thinking' | 'tool' | 'answer' | 'subagent_start' | 'subagent_end';
40→  text?: string;
41→  toolResult?: ToolCallResult;
42→  subagentId?: string;
43→  subagentName?: string;
44→  chart_spec?: {
45→    data: unknown[];
46→    layout?: Record<string, unknown>;
47→  };
48→}
49→
50→export interface ChatMessage {
51→  id: string;
52→  role: 'user' | 'assistant';
53→  content: string;
54→  toolCalls?: ToolCallResult[];
55→  segments?: ContentSegment[];
56→  isStreaming?: boolean;
57→  currentPhase?: 'thinking' | 'answer';
58→}
59→
60→export interface LangfuseStatus {
61→  enabled: boolean;
62→  dashboardUrl: string | null;
63→}
